var BufferedImage = Java.type('java.awt.image.BufferedImage');
var image;
var imageWithParticles;
var width;
var height;
var redColor = 4294901760;
var blueColor = 4278190335;
var greenColor = 4278255360;
var iconWidth = 3;
exports.setup = function() {
	input('map');
	parameter('binaryImage',{'type':'boolean', 'value':true});
	parameter('resolution',{'type':'number', 'value':0.05});
	output('image');
	input('particles');
	input('searchRobot');
	input('target');
}

exports.initialize = function() {

	addInputHandler('map', getOccupancyGrid);
	addInputHandler('particles', function() {
		// add particles to view.
	particleIn = get('particles');
	var res = getParameter('resolution');
	if (particleIn != null) { 
		imageWithParticles = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		//copy the base map and add particles on top of it
		for (i = 0; i < width; i++) {
		   for (j = 0; j < height; j++) {
		   		imageWithParticles.setRGB(i,j,image.getRGB(i,j));
		   }
		}
		for (i = 0 ; i < particleIn.length; i++) {
			var px = particleIn[i].x;
			var py = particleIn[i].y;
			var pixelY = Math.floor(py/res); 
			var pixelX = Math.floor(px/res);
			if (pixelX >= 1 && pixelX < width-1 && 
			pixelY >=1 & pixelY < height-1) { 
				imageWithParticles.setRGB(pixelX, pixelY,redColor);
				imageWithParticles.setRGB(pixelX+1, pixelY,redColor);
				imageWithParticles.setRGB(pixelX-1, pixelY,redColor);
				imageWithParticles.setRGB(pixelX, pixelY-1,redColor);
				imageWithParticles.setRGB(pixelX, pixelY+1,redColor);
			}
		} 
		send('image',imageWithParticles); 
	}

	searchRobotLoc = get('searchRobot');
	if (searchRobotLoc!=null) {
		var x = searchRobotLoc.x;
		var y = searchRobotLoc.y;
		var pixelY = Math.floor(y/res); 
		var pixelX = Math.floor(x/res);
		if (pixelX >= iconWidth && pixelX < width-iconWidth && 
			pixelY >=iconWidth & pixelY < height-iconWidth) {
				for (i = pixelX - iconWidth; i <= pixelX + iconWidth; i++) {
					for (j = pixelY - iconWidth; j <= pixelY + iconWidth; j++) {
						imageWithParticles.setRGB(i, j,blueColor);
					}
				}
			}
	}
	targetLoc = get('target');
	if (targetLoc!=null) {
		var x = targetLoc.x;
		var y = targetLoc.y;
		var pixelY = Math.floor(y/res); 
		var pixelX = Math.floor(x/res);
		if (pixelX >= iconWidth && pixelX < width-iconWidth && 
			pixelY >=iconWidth & pixelY < height-iconWidth) {
				for (i = pixelX - iconWidth; i <= pixelX + iconWidth; i++) {
					for (j = pixelY - iconWidth; j <= pixelY + iconWidth; j++) {
						imageWithParticles.setRGB(i, j,greenColor);
					}
				}
			}
	}
	});
}

function getOccupancyGrid() {

	var mapObject = get('map');
	var imageData = mapObject.grid;
	width = mapObject.width;
	height = mapObject.height;
	print(width);
	print(height);
	var binaryThresholding = getParameter('binaryImage');
	image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
	for (y = 0; y < height; y++) {
		for (x = 0; x < width; x++) { 
			var index = x + y*width;
			var pixel = imageData[index];
			if (pixel < 0) {
				// Opaque red for unknown
				image.setRGB(x, y, 4294901760);
			} else {
				var intensity;
				if ( binaryThresholding ) {
					if ( pixel >= 32768) {
						intensity = 255;
					} else if ( pixel < 10) {
						intensity = 0;
					} else {
						intensity = 127;
					}
				} else {
					intensity = pixel;
				}
				// To make the color opaque:
				var alpha = 4278190080; 
				var color = alpha + intensity * (65536 + 256 + 1);
				image.setRGB(x, y, color);
			}
		}
	} 
	send('image', image);
}
